// Generated by OrchestKit Claude Plugin
// Created: 2026-08-09

/**
 * Credential Read Guard — PreToolUse[Read] Hook
 *
 * Denies Read calls that resolve into a credential file or credential
 * directory in the user's home: SSH private keys, GPG keyrings, AWS
 * credentials, ~/.netrc and ~/.npmrc.
 *
 * WHY THIS EXISTS: `src/settings/ork.settings.json` has declared five
 * `Read(...)` deny rules for these paths since v7, but a PLUGIN
 * settings.json is not a settings scope Claude Code reads, so those
 * rules have never enforced anything. Nothing in the hook estate
 * covered the Read tool either — a probe of
 * `{"tool_name":"Read","tool_input":{"file_path":"~/.ssh/id_rsa"}}`
 * returned rc=0 with no permissionDecision from every registered hook.
 * This hook is the enforcement those declarations always implied.
 *
 * MATCHING IS POST-RESOLUTION. Every candidate path is compared in two
 * forms so neither direction of indirection walks past the guard:
 *   1. the lexically resolved absolute path (`~` expanded, `..` collapsed)
 *      — catches traversal like /tmp/../Users/me/.ssh/id_rsa, and catches
 *        a guarded path that is itself a symlink pointing elsewhere;
 *   2. the realpath (symlinks followed)
 *      — catches a symlink outside the tree that points INTO it, e.g.
 *        /tmp/leak -> ~/.ssh/id_rsa.
 * A hit on EITHER form denies.
 *
 * Ordinary repository files are never touched: every rule is anchored to
 * an absolute path under `os.homedir()`, so a repo-local `.npmrc` or a
 * project `ssh/` directory does not match.
 *
 * @hook PreToolUse[Read]
 * @since v10.0.0-alpha.1
 */

import { homedir } from 'node:os';
import { isAbsolute, resolve } from 'node:path';
import type { HookContext, HookInput, HookResult } from '../../types.js';
import { isReadInput } from '../../types.js';
import { outputDeny, outputSilentSuccess } from '../../lib/common.js';
import { isInsideDir, resolveRealPath } from '../../lib/path-containment.js';
import { NOOP_CTX } from '../../lib/context.js';

const HOOK_NAME = 'credential-read-guard';

interface CredentialRule {
  /** Path relative to the user's home directory, POSIX-style. */
  readonly relative: string;
  /** true = the path and everything beneath it; false = that exact file. */
  readonly tree: boolean;
  /** Human-readable credential class, named in the deny reason. */
  readonly credentialClass: string;
}

/**
 * The five credential classes `ork.settings.json` declares under `deny`.
 * Kept 1:1 with that list — widening this table also widens the contract.
 */
const RULES: readonly CredentialRule[] = [
  { relative: '.ssh', tree: true, credentialClass: 'SSH private keys and known-hosts (~/.ssh)' },
  { relative: '.gnupg', tree: true, credentialClass: 'GPG keyring material (~/.gnupg)' },
  { relative: '.aws/credentials', tree: false, credentialClass: 'AWS access keys (~/.aws/credentials)' },
  { relative: '.netrc', tree: false, credentialClass: 'netrc machine passwords (~/.netrc)' },
  { relative: '.npmrc', tree: false, credentialClass: 'npm registry auth token (~/.npmrc)' },
];

/**
 * Expand a leading `~` against the real home directory.
 *
 * `~otheruser/...` is deliberately NOT expanded: Node cannot resolve
 * another user's home, and the Read tool requires absolute paths, so that
 * form fails before it reaches a file.
 */
function expandHome(filePath: string, home: string): string {
  if (filePath === '~') return home;
  if (filePath.startsWith('~/')) return resolve(home, filePath.slice(2));
  return filePath;
}

/**
 * Does `candidate` fall under `rule`? `candidate` must already be absolute.
 *
 * Matched case-insensitively as well as exactly, because macOS APFS and
 * Windows NTFS are case-insensitive by default: on this machine
 * `~/.SSH/id_rsa` opens the real `~/.ssh/id_rsa`. A case-sensitive compare
 * therefore denies `.ssh` and waves `.SSH` straight through to the same
 * bytes — verified as a live bypass before this branch was added, not a
 * theoretical one.
 *
 * The exact compare is kept first so a genuinely case-sensitive filesystem
 * (ext4, or APFS formatted case-sensitive) still gets precise matching; the
 * folded compare only ever widens the deny, never narrows it. Denying a
 * distinct `~/.SSH` that really is a different directory on a
 * case-sensitive volume is the safe direction to err.
 */
function matchesRule(candidate: string, rule: CredentialRule, home: string): boolean {
  const target = resolve(home, rule.relative);
  if (rule.tree ? isInsideDir(candidate, target) : candidate === target) {
    return true;
  }
  const foldedCandidate = candidate.toLowerCase();
  const foldedTarget = target.toLowerCase();
  return rule.tree
    ? isInsideDir(foldedCandidate, foldedTarget)
    : foldedCandidate === foldedTarget;
}

export function credentialReadGuard(
  input: HookInput,
  ctx: HookContext = NOOP_CTX,
): HookResult {
  try {
    const toolInput = input.tool_input || {};

    // Guard at TOP: not a file read we can reason about.
    if (!isReadInput(toolInput)) {
      return outputSilentSuccess();
    }

    const rawPath = toolInput.file_path;
    if (!rawPath) {
      return outputSilentSuccess();
    }

    const home = homedir();
    const expanded = expandHome(rawPath, home);

    // Lexical resolution: `..` collapsed, relative paths anchored to cwd.
    const lexical = isAbsolute(expanded) ? resolve(expanded) : resolve(process.cwd(), expanded);

    // Symlink resolution. Falls back to the lexical path when the file
    // does not exist, so a non-existent guarded path still denies.
    const real = resolveRealPath(lexical, process.cwd());

    for (const rule of RULES) {
      const viaLexical = matchesRule(lexical, rule, home);
      const viaReal = matchesRule(real, rule, home);
      if (!viaLexical && !viaReal) continue;

      const how = viaLexical ? lexical : `${lexical} -> ${real}`;
      const reason =
        `Blocked: credential file read. ${rule.credentialClass}. ` +
        `The requested path resolves to ${how}, which is inside a guarded ` +
        `credential location. This applies after ~ expansion, .. traversal and ` +
        `symlink resolution, so rewriting the path will not change the answer. ` +
        `If you need a value from this file, ask the user for it directly.`;

      ctx.log(HOOK_NAME, `Denied Read of ${rawPath} (${rule.credentialClass})`, 'warn');
      return outputDeny(reason);
    }

    return outputSilentSuccess();
  } catch (err) {
    // Fail CLOSED is wrong here (it would break every Read on an unrelated
    // bug) and fail OPEN is wrong for a security guard. The only inputs that
    // reach this catch are ones we could not resolve to a path at all, which
    // cannot be a guarded credential path — so pass through, loudly.
    ctx.log(
      HOOK_NAME,
      `Error resolving path, allowing: ${err instanceof Error ? err.message : String(err)}`,
      'warn',
    );
    return outputSilentSuccess();
  }
}

export default credentialReadGuard;
